def get_proverb(proverb_id: int) -> Optional[Dict[str, Any]]:
    """Retrieve a proverb by its unique identifier."""
    for p in PROVERBS_DATA:
        if p["id"] == proverb_id:
            return p
    return None

def get_all_proverbs() -> List[Dict[str, Any]]:
    """Return all curated Kashmiri proverbs."""
    return PROVERBS_DATA

def search_proverbs(query: str) -> List[Dict[str, Any]]:
    """Search proverbs by keyword in Roman, scripts, English/Hindi translations, or tags."""
    q = query.strip().lower()
    results = []
    for p in PROVERBS_DATA:
        if (
            q in p["kashmiri_roman"].lower()
            or q in p["translation_en"].lower()
            or q in p["translation_hi"].lower()
            or q in p.get("cultural_context", "").lower()
            or any(q in t.lower() for t in p.get("tags", []))
            or query.strip() in p["kashmiri_dev"]
            or query.strip() in p["kashmiri_arabic"]
            or query.strip() in p["kashmiri_sharada"]
        ):
            results.append(p)
    return results

def random_proverb() -> Dict[str, Any]:
    """Return a randomly selected Kashmiri proverb."""
    return random.choice(PROVERBS_DATA)
